import { Service, inject } from '@angular/core';
import { MessageService } from 'primeng/api';

export type Severity = 'success' | 'info' | 'warn' | 'error' | 'secondary' | 'contrast'; //other levels are here for future extension

@Service()
export class NotificationService {
  private msgService = inject(MessageService);

  // life (milliseconds) is only passed on when given, otherwise the toast uses the default of the toast component
  private send(severity: Severity, summary: string, detail: string, life?: number): void {
    this.msgService.add({ severity, summary, detail, ...(life === undefined ? {} : { life }) });
  }

  public success(summary: string, detail: string, life?: number) { this.send('success', summary, detail, life); }
  public info(summary: string, detail: string, life?: number)    { this.send('info', summary, detail, life); }
  public warn(summary: string, detail: string, life?: number)    { this.send('warn', summary, detail, life); }
  public error(summary: string, detail: string, life?: number)   { this.send('error', summary, detail, life); }
}
","import { InjectionToken, OnDestroy, Service, computed, inject, signal } from '@angular/core';
import {
  HubConnection,
  HubConnectionBuilder,
  HubConnectionState,
  IRetryPolicy,
  LogLevel,
} from '@microsoft/signalr';
import { Observable } from 'rxjs';

export interface SignalRConfig {
  /** Full hub URL, e.g. https://localhost:5001/hubs/chat */
  url: string;
  /** Return a JWT (or null) for each connection attempt. */
  accessTokenFactory?: () => string | Promise<string>;
  logLevel?: LogLevel;
}

/** Retries after 0s, 2s, 5s, 10s, 30s, then every 30s forever. */
export class BackoffRetryPolicy implements IRetryPolicy {
  private readonly delays = [0, 2000, 5000, 10000, 30000];
  nextRetryDelayInMilliseconds(ctx: { previousRetryCount: number }): number {
    return this.delays[Math.min(ctx.previousRetryCount, this.delays.length - 1)];
  }
}

export type HubConnectionFactory = (config: SignalRConfig) => HubConnection;

/** Builds the real connection. */
export const defaultHubConnectionFactory: HubConnectionFactory = (config) =>
  new HubConnectionBuilder()
    .withUrl(config.url, {
      accessTokenFactory: config.accessTokenFactory,
    })
    .withAutomaticReconnect(new BackoffRetryPolicy())
    .configureLogging(config.logLevel ?? LogLevel.Information)
    .build();

/** How the service gets its connection. A token, so a spec can hand it a stand-in and test without a server. */
export const HUB_CONNECTION_FACTORY = new InjectionToken<HubConnectionFactory>('HUB_CONNECTION_FACTORY', {
  providedIn: 'root',
  factory: () => defaultHubConnectionFactory,
});

@Service()
export class SignalRService implements OnDestroy {
  private readonly createConnection = inject(HUB_CONNECTION_FACTORY);
  private connection?: HubConnection;
  /** Set by stop(), so a connection attempt that is still retrying gives up instead of reconnecting after sign-out. */
  private stopRequested = false;

  private readonly _state = signal<HubConnectionState>(HubConnectionState.Disconnected);
  private readonly _error = signal<string | null>(null);

  readonly state = this._state.asReadonly();
  readonly error = this._error.asReadonly();
  readonly isConnected = computed(() => this._state() === HubConnectionState.Connected);

  /** Build the connection. Register handlers with on() before calling start(). */
  configure(config: SignalRConfig): void {
    if (this.connection) return;

    this.connection = this.createConnection(config);

    const sync = () => this._state.set(this.connection!.state);
    this.connection.onreconnecting((err:any) => {
      this._error.set(err?.message ?? 'Connection lost');
      sync();
    });
    this.connection.onreconnected(() => {
      this._error.set(null);
      sync();
    });
    this.connection.onclose((err:any) => {
      if (err) this._error.set(err.message);
      sync();
    });
  }

  /** Start the connection. Retries the *initial* connect, which
   *  withAutomaticReconnect does not do on its own. */
  async start(maxAttempts = 5): Promise<void> {
    const conn = this.requireConnection();
    if (conn.state !== HubConnectionState.Disconnected) return;

    this.stopRequested = false;
    this._state.set(HubConnectionState.Connecting);
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        await conn.start();
        if (this.stopRequested) {
          // stop() was called while this attempt was in flight
          await conn.stop();
          this._state.set(HubConnectionState.Disconnected);
          return;
        }
        this._error.set(null);
        this._state.set(conn.state);
        return;
      } catch (err) {
        if (this.stopRequested) {
          // stopping on purpose interrupts the attempt; that is not a failure to report or retry
          this._state.set(HubConnectionState.Disconnected);
          return;
        }
        this._error.set((err as Error).message);
        if (attempt === maxAttempts) {
          this._state.set(HubConnectionState.Disconnected);
          throw err;
        }
        await new Promise((r) => setTimeout(r, Math.min(1000 * 2 ** attempt, 15000)));
        if (this.stopRequested) {
          this._state.set(HubConnectionState.Disconnected);
          return;
        }
      }
    }
  }

  async stop(): Promise<void> {
    this.stopRequested = true;
    await this.connection?.stop();
    this._state.set(HubConnectionState.Disconnected);
  }

  /** Subscribe to a server -> client method. Returns an unsubscribe function. */
  on<T extends unknown[]>(method: string, handler: (...args: T) => void): () => void {
    const conn = this.requireConnection();
    conn.on(method, handler as (...args: unknown[]) => void);
    return () => conn.off(method, handler as (...args: unknown[]) => void);
  }

  /** Same as on(), as an Observable. Emits the first argument (or the tuple if several). */
  listen<T = unknown>(method: string): Observable<T> {
    return new Observable<T>((subscriber) => {
      const handler = (...args: unknown[]) =>
        subscriber.next((args.length === 1 ? args[0] : args) as T);
      const conn = this.requireConnection();
      conn.on(method, handler);
      return () => conn.off(method, handler);
    });
  }

  /** Fire-and-forget client -> server call. */
  send(method: string, ...args: unknown[]): Promise<void> {
    return this.requireConnection().send(method, ...args);
  }

  /** Client -> server call that returns the hub method's result. */
  invoke<T = void>(method: string, ...args: unknown[]): Promise<T> {
    return this.requireConnection().invoke<T>(method, ...args);
  }

  /** Server -> client streaming (IAsyncEnumerable / ChannelReader on the hub). */
  stream<T>(method: string, ...args: unknown[]): Observable<T> {
    return new Observable<T>((subscriber) => {
      const sub = this.requireConnection()
        .stream<T>(method, ...args)
        .subscribe({
          next: (v:any) => subscriber.next(v),
          error: (e:any) => subscriber.error(e),
          complete: () => subscriber.complete(),
        });
      return () => sub.dispose();
    });
  }

  ngOnDestroy(): void {
    void this.connection?.stop();
  }

  private requireConnection(): HubConnection {
    if (!this.connection) {
      throw new Error('SignalRService: call configure() before using the connection.');
    }
    return this.connection;
  }
}
","import { inject, Service } from '@angular/core';
import { Observable } from 'rxjs';
import { AuthService } from './auth-service';
import { ConfigService } from './config-service';
import { SignalRService } from './signalr.service';

export interface AppNotification {
  type: string;
  title: string;
  body?: string;
  at: string;
  /** Set when the notification is more than a message, for example 'report.ready'. See report-status-service.ts. */
  event?: string;
  /** What the event is about; for the report events, the report id. */
  correlationId?: string;
}

/** Typed facade over SignalRService for the central hub (OI.Hub: AppHub / IAppClient). */
@Service()
export class AppHubService {
  private hub = inject(SignalRService);
  private auth = inject(AuthService);
  private configService = inject(ConfigService);

  /**
   * Builds the connection (once) without starting it, so handlers can be attached before any message can arrive.
   * The token is read again on every (re)connect, so refreshed tokens are picked up.
   */
  configure(): void {
    this.hub.configure({
      url: this.configService.config.hubUrl,
      accessTokenFactory: () => this.auth.getAccessToken(),
    });
  }

  /** Call after sign-in. */
  async connect(): Promise<void> {
    this.configure();
    await this.hub.start();
  }

  disconnect(): Promise<void> {
    return this.hub.stop();
  }

  // Server -> browser
  readonly messages$: Observable<[string, string]> = this.hub.listen('ReceiveMessage');
  readonly notifications$: Observable<AppNotification> = this.hub.listen('ReceiveNotification');

  // Browser -> server
  sendToMyGroup(groupId: string, text: string) {
    return this.hub.send('SendToMyGroup', groupId, text);
  }
  subscribe(groupId: string, topic: string) {
    return this.hub.invoke('Subscribe', groupId, topic);
  }
  unsubscribe(groupId: string, topic: string) {
    return this.hub.invoke('Unsubscribe', groupId, topic);
  }
}
","import { DestroyRef, effect, inject, InjectionToken, Service, untracked } from '@angular/core';
import { Subscription } from 'rxjs';

import { NotificationService, Severity } from '../utils/notification-service';
import { AppHubService, AppNotification } from './app-hub-service';
import { AuthService } from './auth-service';

/**
 * Something else in the application that wants to see every notification the hub delivers
 * (the OI UI uses this to tell its pages that a report is ready). Register with { provide: HUB_NOTIFICATION_HANDLER, useExisting: ..., multi: true }.
 */
export interface HubNotificationHandler {
  handle(notification: AppNotification): void;
  /** The user signed out: forget anything remembered from notifications. */
  clear(): void;
}

export const HUB_NOTIFICATION_HANDLER = new InjectionToken<HubNotificationHandler[]>('HUB_NOTIFICATION_HANDLER');

const TOAST_LIFE_MS = 10000;
const RETRY_AFTER_MS = 30_000;

/** The hub sends a free-text type; these are the ones that map onto a toast colour, anything else is shown as info. */
const SEVERITY_BY_TYPE: Record<string, Severity> = {
  success: 'success',
  info: 'info',
  warn: 'warn',
  warning: 'warn',
  error: 'error',
};

/**
 * Keeps the browser connected to the central hub for as long as someone is signed in, and shows
 * what the back end sends as toasts. It is started by injecting it once (each application's root component does).
 *
 *  - signed in   -> connect, and listen for notifications
 *  - signed out  -> stop listening and disconnect
 *  - hub down    -> try again every 30 seconds while still signed in
 *
 * The hub only reaches browsers that are connected at that moment; nothing is stored for later.
 */
@Service()
export class HubConnectionService {
  private auth = inject(AuthService);
  private appHub = inject(AppHubService);
  private notifications = inject(NotificationService);
  private handlers = inject(HUB_NOTIFICATION_HANDLER, { optional: true }) ?? [];

  private subscription?: Subscription;
  private retryTimer?: ReturnType<typeof setTimeout>;
  /** Sign-in and sign-out can happen in quick succession; the work is done strictly one after another. */
  private queue: Promise<void> = Promise.resolve();

  constructor() {
    effect(() => {
      const signedIn = this.auth.isAuthenticated();
      untracked(() => this.enqueue(signedIn ? () => this.start() : () => this.stop()));
    });
    inject(DestroyRef).onDestroy(() => this.cancelRetry());
  }

  private enqueue(work: () => Promise<void>): void {
    this.queue = this.queue.then(work).catch((error: unknown) => {
      console.error('Hub connection error', error);
    });
  }

  private async start(): Promise<void> {
    if (this.subscription) {
      return;   // already running
    }
    // listen before connecting so a message sent the moment the connection opens is not missed
    this.appHub.configure();
    this.subscription = this.appHub.notifications$.subscribe((notification) => {
      this.handlers.forEach((handler) => handler.handle(notification));   // e.g. lets pages know a report is ready or failed
      this.show(notification);
    });
    await this.connect();
  }

  private async connect(): Promise<void> {
    try {
      await this.appHub.connect();
    } catch (error) {
      console.error('Could not connect to the notification hub; will try again', error);
      this.retryTimer = setTimeout(() => this.enqueue(() => this.retry()), RETRY_AFTER_MS);
    }
  }

  private async retry(): Promise<void> {
    this.retryTimer = undefined;
    if (this.subscription) {   // still signed in
      await this.connect();
    }
  }

  private async stop(): Promise<void> {
    if (!this.subscription) {
      return;   // never started
    }
    this.cancelRetry();
    this.subscription.unsubscribe();
    this.subscription = undefined;
    this.handlers.forEach((handler) => handler.clear());
    await this.appHub.disconnect();
  }

  private cancelRetry(): void {
    if (this.retryTimer !== undefined) {
      clearTimeout(this.retryTimer);
      this.retryTimer = undefined;
    }
  }

  private show(notification: AppNotification): void {
    const severity = SEVERITY_BY_TYPE[notification.type?.toLowerCase() ?? ''] ?? 'info';
    this.notifications[severity as 'success' | 'info' | 'warn' | 'error'](notification.title, notification.body ?? '', TOAST_LIFE_MS);
  }
}
